questionvariables.text:
funcidx : rand(3);                        /* 0 sin, 1 cos, 2 tan */
fname : if funcidx=0 then "sin" elseif funcidx=1 then "cos" else "tan";
quadrant : rand(4);                       /* which quadrant the angle lands in, 0..3 */
baseangle : if funcidx=2 then [30,60][rand_with_prohib(1,2,[])] else [30,60,90][rand_with_prohib(1,3,[])];
angledeg : quadrant*90 + baseangle;
/* reference values at 30/60/90 */
refsin : if baseangle=30 then 1/2 elseif baseangle=60 then sqrt(3)/2 else 1;
refcos : if baseangle=30 then sqrt(3)/2 elseif baseangle=60 then 1/2 else 0;
reftan : if baseangle=90 then und else refsin/refcos;
/* sign in each quadrant: Q0 (0-90) all positive; Q1 (90-180) sin+ cos- tan-;
   Q2 (180-270) sin- cos- tan+; Q3 (270-360) sin- cos+ tan- */
sinsign : if quadrant=0 then 1 elseif quadrant=1 then 1 elseif quadrant=2 then -1 else -1;
cossign : if quadrant=0 then 1 elseif quadrant=1 then -1 elseif quadrant=2 then -1 else 1;
tansign : sinsign*cossign;
ta : if funcidx=0 then sinsign*refsin elseif funcidx=1 then cossign*refcos else tansign*reftan;
wrong_nosign : if funcidx=0 then refsin elseif funcidx=1 then refcos else reftan;   /* forgot the sign for the quadrant */
quadrantnum : quadrant+1;
signword : if funcidx=0 then (if sinsign=1 then "positive" else "negative")
           elseif funcidx=1 then (if cossign=1 then "positive" else "negative")
           else (if tansign=1 then "positive" else "negative");
